		return switch (ordinal) {
		case 0 -> logConventionalRows;
		case 1 -> logExpectedInvocations;
		case 2 -> boundInputCardinality;
		case 3 -> normalizedProvenRangeWidth;
		case 4 -> operatorFanIn;
		default -> throw new IndexOutOfBoundsException("learning feature ordinal outside envelope: " + ordinal);
		};
